<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api,fmtDate,labels} from '../services/api';import {usePage} from '../services/usePage';import {useAuth} from '../stores/auth';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import StatusBadge from '../components/StatusBadge.vue';import {ArrowUpRight,ScanLine,Images,Database,CheckCheck,Clock3,ArrowRight,Leaf} from 'lucide-vue-next';import {Doughnut} from 'vue-chartjs';import {Chart as ChartJS,ArcElement,Tooltip,Legend} from 'chart.js'
ChartJS.register(ArcElement,Tooltip,Legend)
const data=ref<any>(null),auth=useAuth();const {error,act}=usePage();onMounted(()=>act(async()=>{data.value=(await api.get('dashboard/')).data}))
const chart=computed(()=>({labels:(data.value?.states||[]).map((x:any)=>labels[x.state]),datasets:[{data:(data.value?.states||[]).map((x:any)=>x.count),backgroundColor:['#153e2e','#b9d879','#e9b96c','#d3d9d1'],borderWidth:4,borderColor:'#fff'}]}))
</script>
<template><Notice :error="error"/><div class="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p class="section-label">UNA MIRADA A TU INVESTIGACIÓN</p><h1 class="heading mt-2">Hola, {{auth.user?.first_name||auth.user?.username}} <span class="text-emerald-600">.</span></h1><p class="subheading">Tu laboratorio, tus datos y el siguiente paso de tu investigación.</p></div><RouterLink to="/detection" class="btn"><ScanLine :size="17"/>Nueva inspección</RouterLink></div>
<section class="relative mb-7 overflow-hidden rounded-2xl bg-forest p-7 text-white md:p-9"><div class="relative z-10 max-w-xl"><span class="rounded-full border border-white/20 px-3 py-1 text-[10px] uppercase tracking-widest text-lime">Visión computacional aplicada</span><h2 class="mt-5 text-3xl font-medium tracking-tight">De la imagen a la evidencia.</h2><p class="mt-3 max-w-md text-sm leading-6 text-white/60">Organiza tu dataset, revisa cada lesión y construye modelos con resultados que puedas explicar.</p><RouterLink to="/datasets" class="mt-5 inline-flex items-center gap-2 text-sm font-semibold text-lime">Explorar mis datos<ArrowRight :size="17"/></RouterLink></div><Leaf class="absolute -right-8 -bottom-16 h-80 w-80 rotate-[-20deg] text-lime/10" :stroke-width=".8"/><div class="absolute right-20 top-9 hidden h-36 w-36 rounded-[45%] border border-lime/25 md:block"></div></section>
<template v-if="data"><div class="mb-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="metric in [{label:'Imágenes en el laboratorio',value:data.images,icon:Images,hint:'Originales registrados'},{label:'Datasets disponibles',value:data.datasets,icon:Database,hint:'Colecciones de investigación'},{label:'Imágenes revisadas',value:data.reviewed,icon:CheckCheck,hint:'Con validación humana'},{label:'Inspecciones realizadas',value:data.inspections,icon:ScanLine,hint:'Incluye trabajos pendientes'}]" :key="metric.label" class="card"><div class="flex items-center justify-between"><span class="text-xs text-slate-500">{{metric.label}}</span><component :is="metric.icon" class="text-emerald-700" :size="18"/></div><p class="mt-5 text-4xl font-semibold tracking-tight text-forest">{{metric.value.toLocaleString()}}</p><p class="mt-2 text-[11px] text-slate-400">{{metric.hint}}</p></div></div>
<div class="grid gap-6 xl:grid-cols-3"><section class="card xl:col-span-2"><div class="mb-5 flex items-center justify-between"><h2 class="font-semibold">Actividad de inspección</h2><RouterLink to="/inspections" class="text-xs font-semibold text-emerald-700">Ver historial ↗</RouterLink></div><div v-if="data.recent.length" class="table-wrap"><table class="data-table"><thead><tr><th>Imagen</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><tr v-for="row in data.recent" :key="row.id"><td><RouterLink :to="'/inspections/'+row.id" class="font-medium text-forest">{{row.name}}</RouterLink></td><td><StatusBadge :value="row.job.state"/></td><td class="text-xs text-slate-400">{{fmtDate(row.created_at)}}</td></tr></tbody></table></div><EmptyState v-else title="Tu primera inspección empieza aquí" text="Cuando tengas un modelo entrenado, podrás analizar imágenes y consultar aquí los resultados."/></section>
<section class="card"><h2 class="font-semibold">Composición del dataset</h2><p class="mt-1 text-xs text-slate-400">Estados de revisión de imágenes</p><div v-if="data.images" class="mx-auto mt-6 max-w-60"><Doughnut :data="chart" :options="{cutout:'78%',plugins:{legend:{position:'bottom',labels:{boxWidth:8,padding:18,font:{size:10}}}}}"/></div><p v-else class="py-14 text-center text-sm text-slate-400">Importa tu dataset para ver su distribución.</p></section></div>
<div class="mt-6 grid gap-5 md:grid-cols-2"><section class="card flex items-center gap-4"><div class="rounded-xl bg-emerald-50 p-3"><Leaf class="text-emerald-700"/></div><div><p class="text-xs text-slate-400">MODELO ACTIVO</p><p class="mt-1 font-semibold">{{data.active_model?.name||'Ningún modelo activado'}}</p><p class="mt-1 text-xs text-slate-500">{{data.active_model?'Listo para nuevas inspecciones':'Entrena y valida un modelo antes de activarlo.'}}</p></div></section><section class="card flex items-center gap-4"><div class="rounded-xl bg-amber-50 p-3"><Clock3 class="text-amber-700"/></div><div><p class="text-xs text-slate-400">INFERENCIA PROMEDIO</p><p class="mt-1 font-semibold">{{data.mean_inference_ms===null?'Sin mediciones':data.mean_inference_ms.toFixed(1)+' ms'}}</p><p class="mt-1 text-xs text-slate-500">Mediciones reales del servidor; incluye carga inicial cuando corresponda.</p></div></section></div></template><div v-else class="card text-sm text-slate-400">Cargando datos del laboratorio…</div></template>
